            class AsmObject {
                constructor(id, description) {
                    this.id = id;
                    this.description = description;
                    this.sizeAdj = 0;
                    this.users = [];
                }
                get size() {
                    return (this.endLocation - this.startLocation) - this.sizeAdj;
                }
            }
